package com.tekwatt.payment.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity @Table(name="wallets",uniqueConstraints=@UniqueConstraint(columnNames={"tenant_id","user_id"}))public class Wallet{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID userId;@Column(nullable=false,precision=14,scale=2)private BigDecimal balance;@Column(nullable=false,length=3)private String currency;@Column(nullable=false,length=20)private String status;@Column(nullable=false)private Instant updatedAt;protected Wallet(){}public Wallet(UUID t,UUID u,String c){id=UUID.randomUUID();tenantId=t;userId=u;currency=c;balance=BigDecimal.ZERO;status="ACTIVE";updatedAt=Instant.now();}public void adjust(BigDecimal amount){balance=balance.add(amount);if(balance.signum()<0)throw new IllegalArgumentException("Insufficient wallet balance");updatedAt=Instant.now();}public void status(String s){status=s;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getUserId(){return userId;}public BigDecimal getBalance(){return balance;}public String getCurrency(){return currency;}public String getStatus(){return status;}public Instant getUpdatedAt(){return updatedAt;}}
